public class StepLoggerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.List<String> calm = new java.util.ArrayList<>();
        boolean calmThrew = false;
        try {
            StepLogger.run(calm, false);
        } catch (RuntimeException e) {
            calmThrew = true;
        }
        check("explode=false does not throw", false, calmThrew);
        check("explode=false log order", "[start, work-done, cleanup]", calm.toString());

        java.util.List<String> boom = new java.util.ArrayList<>();
        boolean boomThrew = false;
        try {
            StepLogger.run(boom, true);
        } catch (RuntimeException e) {
            boomThrew = true;
        }
        check("explode=true throws RuntimeException", true, boomThrew);
        check("explode=true log order", "[start, work-failed, cleanup]", boom.toString());
        check("cleanup is last even after throw", "cleanup",
                boom.isEmpty() ? "(empty log)" : boom.get(boom.size() - 1));
        check("start is always first", "start",
                boom.isEmpty() ? "(empty log)" : boom.get(0));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

