public class StepLogger {

    public static void run(java.util.List<String> log, boolean explode) {
        log.add("start");
        try {
            if (explode) {
                log.add("work-failed");
                throw new RuntimeException("work exploded");
            }
            log.add("work-done");
        } finally {
            log.add("cleanup");
        }
    }
}
